// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "GET", "template": "/v1/search", "require_user": true, "idempotent": false, "required_consents": ["terms", "privacy"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.api.search > "Validate query"
// GET /v1/search?q=&jurisdiction=&max_rent=&currency=&period=&lat=&lng=&near=&radius_m=&limit=&use_profile=
// max_rent is in minor units of currency (spec 4.2); near is a place name resolved by the
// local gazetteer; use_profile=true fills missing filters from the saved profile.
const gw = $input.first().json;
const q = gw.ctx.query || {};
const user = gw.ctx.user || {};
const details = [];
const allowed = ['q', 'jurisdiction', 'max_rent', 'currency', 'period', 'lat', 'lng', 'near', 'radius_m', 'limit', 'use_profile'];
for (const k of Object.keys(q)) if (!allowed.includes(k)) details.push({ field: k, issue: 'unknown_parameter' });
const str = (k) => (q[k] === undefined || q[k] === null ? '' : String(q[k]).trim());
const int = (k, lo, hi) => {
  const v = str(k);
  if (!v) return null;
  if (!/^\d{1,12}$/.test(v) || Number(v) < lo || Number(v) > hi) { details.push({ field: k, issue: `must_be_integer_${lo}_${hi}` }); return null; }
  return Number(v);
};
const num = (k, lo, hi) => {
  const v = str(k);
  if (!v) return null;
  const n = Number(v);
  if (!/^-?\d{1,3}(\.\d{1,8})?$/.test(v) || n < lo || n > hi) { details.push({ field: k, issue: `must_be_number_${lo}_${hi}` }); return null; }
  return n;
};
const text = str('q');
if (Array.from(text).length > 300) details.push({ field: 'q', issue: 'too_long', max: 300 });
const jurisdiction = str('jurisdiction');        // explicit; else the profile's (use_profile), else the account's
if (jurisdiction && !/^[A-Z]{2}(-[A-Z0-9]{1,3})?$/.test(jurisdiction)) details.push({ field: 'jurisdiction', issue: 'invalid_format' });
const max_rent = int('max_rent', 0, 1e12);
const currency = str('currency').toUpperCase() || null;
if (currency && !/^[A-Z]{3}$/.test(currency)) details.push({ field: 'currency', issue: 'invalid_format' });
const period = str('period') || null;
if (period && !['month', 'week'].includes(period)) details.push({ field: 'period', issue: 'must_be_month_or_week' });
const lat = num('lat', -90, 90), lng = num('lng', -180, 180);
if ((lat === null) !== (lng === null)) details.push({ field: lat === null ? 'lat' : 'lng', issue: 'lat_and_lng_go_together' });
const near = str('near');
if (Array.from(near).length > 120) details.push({ field: 'near', issue: 'too_long', max: 120 });
const radius_m = int('radius_m', 100, 100000);
const limit = int('limit', 1, 50);
const up = str('use_profile');
if (up && !['true', 'false'].includes(up)) details.push({ field: 'use_profile', issue: 'must_be_true_or_false' });
if (!jurisdiction && up !== 'true' && !user.jurisdiction_code) details.push({ field: 'jurisdiction', issue: 'required' });
if (details.length) {
  return [{ json: { ok: false, status: 422, gw, error: { code: 'VALIDATION_FAILED', message: 'Query parameters are invalid', details } } }];
}
const input = { q: text, jurisdiction: jurisdiction || null, account_jurisdiction: user.jurisdiction_code || null, max_rent_minor: max_rent, currency, budget_period: period,
  lat, lng, place: near || null, radius_m, limit };
return [{ json: { ok: true, gw, input, params: [gw.ctx.user_id || '', up === 'true'] } }];

// wf.api.search > "Search input"
// Explicit query parameters win; with use_profile=true, missing ones come from the saved profile.
const v = $('Validate query').first().json;
const prof = $input.first().json.profile || null;
const i = { ...v.input };
const used = [];
if (prof) {
  if (!i.jurisdiction && prof.jurisdiction_code) { i.jurisdiction = prof.jurisdiction_code; used.push('jurisdiction'); }
  if (i.max_rent_minor === null && prof.budget_max_minor !== null) {
    i.max_rent_minor = prof.budget_max_minor; i.currency = prof.currency; i.budget_period = prof.budget_period; used.push('budget');
  }
  if (i.lat === null && !i.place && prof.lat !== null && prof.lng !== null) {
    i.lat = prof.lat; i.lng = prof.lng; if (i.radius_m === null) i.radius_m = prof.radius_m; used.push('anchor');
  }
}
if (!i.jurisdiction) i.jurisdiction = i.account_jurisdiction;
delete i.account_jurisdiction;
return [{ json: { ...i, profile_fields_used: used, no_jurisdiction: !i.jurisdiction } }];

// wf.api.search > "Build result"
const v = $('Validate query').first().json;
const r = $input.first().json;
const si = $('Search input').first().json;
if (!r.ok) {
  return [{ json: { ok: false, gw: v.gw, status: 422, error: { code: 'VALIDATION_FAILED', message: 'Query parameters are invalid',
    details: [{ field: 'jurisdiction', issue: r.error_code || 'unknown' }] } } }];
}
return [{ json: { ok: true, gw: v.gw, status: 200,
  data: { mode: r.mode, count: r.count, results: r.results, applied: { ...r.applied, profile_fields_used: si.profile_fields_used },
          warnings: r.warnings, data_attribution: ['openstreetmap'] },
  meta: { timings: r.timings },
  steps: [{ agent: 'A3_match', model: r.applied && r.applied.vector ? 'bge-m3' : null, input: { mode: r.mode },
            output: { count: r.count, warnings: r.warnings }, latency_ms: r.timings.total_ms,
            tool_calls: [{ tool: 'app.search_public', db_ms: r.timings.db_ms, embed_ms: r.timings.embed_ms }] }] } }];

// wf.api.search > "No jurisdiction": use_profile=true but neither the request nor a profile names one.
const v = $('Validate query').first().json;
return [{ json: { ok: false, gw: v.gw, status: 422, error: { code: 'VALIDATION_FAILED', message: 'Query parameters are invalid',
  details: [{ field: 'jurisdiction', issue: 'required' }] } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
